/**
 * What: Unit tests for GET /api/cron - every auth branch and runTick invocation:
 *       secret unset (rejection), secret set + correct auth (success), secret set + wrong auth (rejection).
 * Why: This route controls access to the automation scheduler; an open endpoint would
 *      allow any anonymous request to trigger drafts and notifications. /plan-eng-review
 *      mandates that a missing CRON_SECRET fails loud (401), not fail open.
 * How: Stubbed process.env and runTick; each test builds a Request with or without
 *      Authorization header, asserts status and whether runTick was called.
 * From Where: T-004 ticket, 2026-08.
 * When: 2026-08.
 */

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { GET } from "./route";

function makeRequest(authHeader?: string): Request {
  const headers = new Headers();
  if (authHeader) {
    headers.set("Authorization", authHeader);
  }
  return new Request("http://localhost/api/cron", {
    method: "GET",
    headers,
  });
}

let savedCronSecret: string | undefined;
let runTickMock: ReturnType<typeof vi.fn>;

beforeEach(() => {
  savedCronSecret = process.env.CRON_SECRET;
  delete process.env.CRON_SECRET;

  vi.spyOn(console, "error").mockImplementation(() => {});
  vi.spyOn(console, "warn").mockImplementation(() => {});
});

afterEach(() => {
  if (savedCronSecret === undefined) {
    delete process.env.CRON_SECRET;
  } else {
    process.env.CRON_SECRET = savedCronSecret;
  }
  vi.unstubAllEnvs();
  vi.restoreAllMocks();
});

describe("GET /api/cron", () => {
  it("rejects the request (401) when CRON_SECRET is unset", async () => {
    const res = await GET(makeRequest());
    expect(res.status).toBe(401);
    const body = await res.text();
    expect(body).toBe("Unauthorized");
  });

  it("rejects the request (401) when CRON_SECRET is unset even with an authorization header", async () => {
    const res = await GET(makeRequest("Bearer some-secret"));
    expect(res.status).toBe(401);
    const body = await res.text();
    expect(body).toBe("Unauthorized");
  });

  it("rejects the request (401) when CRON_SECRET is set but the authorization header is missing", async () => {
    process.env.CRON_SECRET = "test-secret-123";
    const res = await GET(makeRequest());
    expect(res.status).toBe(401);
    const body = await res.text();
    expect(body).toBe("Unauthorized");
  });

  it("rejects the request (401) when CRON_SECRET is set but the authorization header is wrong", async () => {
    process.env.CRON_SECRET = "test-secret-123";
    const res = await GET(makeRequest("Bearer wrong-secret"));
    expect(res.status).toBe(401);
    const body = await res.text();
    expect(body).toBe("Unauthorized");
  });

  it("succeeds (200) when CRON_SECRET is set and the authorization header is correct", async () => {
    process.env.CRON_SECRET = "test-secret-123";
    const res = await GET(makeRequest("Bearer test-secret-123"));
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.ok).toBe(true);
    expect(body.ranAt).toBeDefined();
    expect(body.clients).toBeDefined();
    expect(Array.isArray(body.clients)).toBe(true);
  });
});

